"""Independent FastMCP exercise; all scientific oracles were generated by direct R."""
import asyncio
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys
import pytest
from fastmcp import Client
from fastmcp.exceptions import ToolError

ROOT = Path(__file__).resolve().parents[3]
OUT = ROOT/'reports/verification/quickstart'
sys.path.insert(0,str(ROOT/'src'))
from tools.quickstart import quickstart_mcp

def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def invoke(tool,args):
    async def run():
        async with Client(quickstart_mcp) as client:
            return (await client.call_tool(tool,args)).data
    return asyncio.run(run())

def artifact(result,kind):
    return Path(next(a['path'] for a in result['artifacts'] if a['kind']==kind))

@pytest.fixture(scope='session',autouse=True)
def setup():
    os.environ.update(P2A_PROJECT_ROOT=str(ROOT),P2A_RSCRIPT='/usr/local/bin/Rscript',P2A_R_PROJECT=str(ROOT/'r-runtime'))
    immutable={str(p):sha(p) for p in (ROOT/'notebooks/quickstart/reference').glob('*') if p.is_file()}
    source=json.loads((ROOT/'notebooks/quickstart/source_hashes_before.json').read_text())
    assert all(sha(ROOT/'repo/occJSDM'/p)==h for p,h in source.items())
    (OUT/'immutable_before.json').write_text(json.dumps(immutable,indent=2)+'\n')
    yield
    assert all(sha(p)==h for p,h in immutable.items())
    assert all(sha(ROOT/'repo/occJSDM'/p)==h for p,h in source.items())

